import {CALCULATIONS} from './scenario-variables.js?v=city-library-1';
import {SCENARIO_SOUNDS} from './scenario-sounds.js?v=city-library-1';
import {BUSINESSES} from './business.js?v=city-library-1';
import {REWARDS} from './rewards.js?v=city-library-1';
import {areaFields,refreshAreaFields,readAreaFields} from './scenario-area-ui.js?v=city-library-1';
import {STORY_VALUES,expandScenarioText} from './scenario-text.js?v=city-library-1';
import {SCENARIO_EVENTS} from './scenario-events.js?v=city-library-1';
import {CUSTOM_METRICS,attachCustomScenario} from './custom-scenarios.js?v=city-library-1';
const metricOptions=(selected='',directions=false)=>['City and development','Structure counts'].map(group=>`<optgroup label="${group}">${Object.entries(CUSTOM_METRICS).filter(([,m])=>(m.group||'City and development')===group).map(([key,m])=>`<option value="${key}" ${key===selected?'selected':''}>${m.name}${directions?' · '+m.direction:''}</option>`).join('')}</optgroup>`).join('');
const conditionFields=(id,label)=>`<label>${label}<select id="eventCondition${id}"><option value="">No condition</option>${metricOptions()}</select></label><label>Comparison<select id="eventOperator${id}"><option value="gte">At least</option><option value="lte">At most</option></select></label><label>Threshold<input id="eventThreshold${id}" type="number" step="any" value="50"></label>${areaFields('event'+id)}`;
export function showCustomScenarioEditor(ui,done){const {city,dialog,exportCity,save,update,clearUndo}=ui,c=city(),$=s=>document.querySelector(s);if(c.emergency.active){dialog('Finish the emergency first','<p>Resolve the active disaster before creating a challenge.</p>');return;}
 dialog('Create a city challenge',`<p>Use this city as the starting point. Set one to four goals to meet together or complete as sequential stages within your deadline. This replaces any current challenge goals and keeps your city.</p><details><summary>How goal counts work</summary><p>Use Count location for structure counts within a circular radius of a map coordinate. Coordinates run from 1 to 48; radius 0 counts only the center tile. Multi-tile farms and landmarks count once at their origin tile. A building outside the area does not qualify. You can repeat a structure goal for different neighborhoods. Abandoned RCI goals count formerly occupied buildings that are now empty, not newly zoned land or rubble. Farms count once at the barn. Restore services and demand to encourage recovery, or bulldoze the empty building. Ordinance goals require a policy to be enacted or repealed. Ordinance event conditions watch the same live policy state. Agriculture goals count developed farms once per barn, not individual fields. Clean-industry goals count developed clean industrial buildings. Empty industrial zones do not count. Structure counts require a standing building, whether or not it has power, water or road access. Airports and seaports must be developed; empty facility zoning does not count. Each multi-tile structure counts once at its origin. Infrastructure goals count operating facilities and actual commuters. Business goals count placed buildings and current monthly payments; accepted permits alone do not qualify. Landmark goals count standing buildings, including a specific landmark if selected. Scheduled attacks must finish before victory; rebuilding a destroyed landmark satisfies the goal. Utility goals count occupied homes without service; pair them with a population goal to require a living city.</p></details><label>Challenge title<input id="customTitle" maxlength="60" value="My city challenge"></label><details><summary>Briefing and outcome messages (optional)</summary><p>Explain the starting situation and give players instructions. Each message allows 1,500 characters. Line breaks are preserved.</p><label>Briefing<textarea id="customBriefing" maxlength="1500" rows="5"></textarea></label><label>Win message<textarea id="customWinMessage" maxlength="1500" rows="3"></textarea></label><label>Loss message<textarea id="customLossMessage" maxlength="1500" rows="3"></textarea></label><p>Insert live values such as {population}, {funds} or {farms}. Values are filled in whenever the player opens Scenario status. Unknown placeholders remain plain text.</p><div class="service-funding"><label>Message<select id="storyTarget"><option value="customBriefing">Briefing</option><option value="customWinMessage">Win message</option><option value="customLossMessage">Loss message</option></select></label><label>Live value<select id="storyValue">${Object.entries(STORY_VALUES).map(([key,value])=>`<option value="${key}">${value.name}</option>`).join('')}</select></label></div><div class="actions"><button id="insertStoryValue">Insert at cursor</button><button id="previewStory">Preview selected message</button></div><p id="storyPreview" role="status" style="white-space:pre-wrap"></p></details><div class="service-funding"><label>Starting pace<select id="customSpeed"><option value="1">1× · Normal</option><option value="3">3× · Fast</option><option value="8">8× · Very fast</option></select></label><label><input id="customSpeedLocked" type="checkbox">Lock the running pace</label></div><p>A new challenge starts at this pace after you close its briefing. Pausing remains available, including for construction and dialogs. Imported cities remain paused until resumed.</p><label>Deadline in months<input id="customMonths" type="number" min="12" max="1200" step="1" value="60"></label><label>Completion rule<select id="customCompletionMode"><option value="goals">Complete goals (ending events may override)</option><option value="scripted">Only an End scenario event can grant victory</option></select></label><p>End scenario events resolve victory or loss when their conditions match. Their result message is saved, later actions stop, and outcome ranks still apply. Scripted mode tracks goals without granting automatic victory. If no ending triggers by the deadline, the challenge is lost.</p><label>Goal progression<select id="customObjectiveMode"><option value="together">Meet all goals together</option><option value="sequence">Complete stages in order</option></select></label><p>Sequential stages use goal row order. Hold each stage before advancing; only one stage can complete per month. Completed stages remain complete even if the city later changes. You may repeat a metric with different targets. Events can react to Completed scenario stages, beginning on the following monthly check after an intermediate stage. Scenario scripts stop at victory; use the win message for the final outcome.</p><label>Consecutive months to hold goals or each stage<input id="customHoldMonths" type="number" min="1" max="1200" step="1" value="1"></label><p>Use 1 for a single monthly check. Longer periods reset if any goal is missed. In simultaneous mode, required events and emergency response must finish before the streak begins. In stage mode, required events still block final victory.</p>${[0,1,2,3].map(i=>`<div class="service-funding"><label>Goal ${i+1}<select id="customMetric${i}"><option value="">${i?'No additional goal':'Choose a goal'}</option>${metricOptions(i===0?'population':'',true)}</select></label><label>Target<input id="customTarget${i}" type="number" step="any" value="400"></label>${areaFields('goal'+i)}</div>`).join('')}<details><summary>Outcome ranks (optional)</summary><p>Define up to four ratings in priority order. At the end, the first rank matching the outcome and all/any selected conditions is awarded. Leave conditions empty for a fallback rank. Ranks evaluate the final city and saved counters; they do not change victory requirements. The standard time-based rank applies if none match. Names allow 60 characters and result messages allow 500; messages support live values, captured when awarded.</p>${[0,1,2,3].map(i=>`<div class="service-funding"><label>Rank ${i+1} name (blank to omit)<input id="rankName${i}" maxlength="60"></label><label>Eligible outcome<select id="rankOutcome${i}"><option value="won">Victory</option><option value="lost">Deadline loss</option><option value="either">Either outcome</option></select></label><label style="grid-column:1 / -1">Result message<textarea id="rankMessage${i}" maxlength="500" rows="3"></textarea></label><label>Match<select id="eventMatchrank${i}"><option value="all">All selected conditions</option><option value="any">Any selected condition</option></select></label>${conditionFields('rank'+i,'Rank condition 1')}<details style="grid-column:1 / -1"><summary>More rank conditions</summary>${[1,2,3].map(j=>`<div class="service-funding">${conditionFields('rank'+i+'_'+j,'Rank condition '+(j+1))}</div>`).join('')}</details></div>`).join('')}</details><details><summary>Scenario variables (optional)</summary><p>Four named counters remember scenario progress. Use Scenario variable 1–4 in goals and event conditions, and {variable1}–{variable4} in messages. Events can set a value, increment it, copy a current metric, or calculate from two constants, live metrics or saved variables. Calculations include addition, subtraction, multiplication, division, percentages and bounded random integers. For a relative growth goal, copy population into Variable 1, repeatedly calculate Population as a percentage of Variable 1 into Variable 2, then require Variable 2 to reach 150. Values are whole numbers capped at ±1,000,000; copied metrics round to the nearest integer. Changes persist even if the city later regresses.</p>${[0,1,2,3].map(i=>`<div class="service-funding"><label>Variable ${i+1} name<input id="variableName${i}" maxlength="40" value="Variable ${i+1}"></label><label>Initial value<input id="variableInitial${i}" type="number" min="-1000000" max="1000000" step="1" value="0"></label></div>`).join('')}</details><details><summary>Schedule events (optional)</summary><label>Event timing<select id="customEventMode"><option value="together">Run eligible actions together</option><option value="monthly">One event per month (legacy timing)</option></select></label><p>Variable actions update saved counters before later actions in the same group check their conditions. Use negative Add values to subtract. Copy metric uses the citywide value. Choose up to four actions before the deadline. Grouped actions may share a month and run in row order when equally due. A disaster stops the group; later actions wait until the next simulation month after it ends. Earlier unread popups hold later groups. Within a group, the last camera view, sound and news message is presented; all popup messages remain available in order. Move and zoom city view centers the chosen map coordinates at the selected zoom. Play sound delivers an original cue using the player’s sound preferences; muted cues are still recorded in Scenario status. Popup messages pause play for reading, with an optional Scenario status button. Offer business deal presents a proposal in City desk → Business deals without accepting it or placing a building. Scheduled repeats can offer a declined proposal again; pending and accepted offers stay unchanged. Offer reward unlocks the selected building in City desk → Rewards, without placing it or charging construction costs. Already-earned rewards stay earned. Announcements deliver text in the news bar without starting an emergency. You can use live values such as {population} or {funds}; the latest delivered message stays in Scenario status. Map coordinates run from 1 to 48. With no conditions, an event runs on its schedule. Choose up to four conditions and require all (AND) or any (OR) to be true. Conditions are checked together monthly from the start month onward. Conditional events can be avoided and do not have to trigger to win. Events use the nearest suitable target; if none exists they are recorded as skipped.</p>${[0,1,2,3].map(i=>`<div class="service-funding"><label>Event ${i+1}<select id="customEvent${i}"><option value="">None</option>${Object.entries(SCENARIO_EVENTS).map(([k,name])=>`<option value="${k}">${name}</option>`).join('')}</select></label><div id="eventVariableFields${i}" style="grid-column:1 / -1"><label>Variable slot<select id="eventVariable${i}">${[0,1,2,3].map(j=>`<option value="${j}">Variable ${j+1}</option>`).join('')}</select></label><label>Operation<select id="eventOperation${i}"><option value="set">Set to value</option><option value="add">Add value (negative subtracts)</option><option value="copy">Copy current metric</option><option value="calculate">Calculate from two values</option></select></label><label>Value<input id="eventValue${i}" type="number" min="-1000000" max="1000000" step="1" value="1"></label><label>Metric to copy<select id="eventCopyMetric${i}">${metricOptions('population')}</select></label><div id="eventCalculationFields${i}"><label>Calculation<select id="eventCalculation${i}">${Object.entries(CALCULATIONS).map(([key,name])=>`<option value="${key}">${name}</option>`).join('')}</select></label>${['left','right'].map(side=>`<div class="service-funding"><label>${side==='left'?'Left':'Right'} operand<select id="eventOperandKind${side}${i}"><option value="constant">Constant</option><option value="metric">Live metric or saved variable</option></select></label><label>Number<input id="eventOperandValue${side}${i}" type="number" min="-1000000" max="1000000" step="1" value="1"></label><label>Metric<select id="eventOperandMetric${side}${i}">${metricOptions('population')}</select></label></div>`).join('')}<p>Both operands are read before the result is stored. Saved variables appear in the metric list. Results round to whole numbers and stop at ±1,000,000. Division by zero leaves the variable unchanged and records the failed occurrence. Random bounds round to integers, include both endpoints, and reproduce for the same city seed, month and action.</p></div></div><label id="eventOutcomeLabel${i}">Ending outcome<select id="eventOutcome${i}"><option value="won">Victory</option><option value="lost">Loss</option></select></label><label id="eventZoomLabel${i}">Camera zoom (%)<input id="eventZoom${i}" type="number" min="40" max="250" step="1" value="150"></label><label id="eventSoundLabel${i}">Sound cue<select id="eventSound${i}">${Object.entries(SCENARIO_SOUNDS).map(([key,s])=>`<option value="${key}">${s.name}</option>`).join('')}</select></label><label id="eventBusinessLabel${i}">Business deal<select id="eventBusiness${i}">${Object.entries(BUSINESSES).map(([key,b])=>`<option value="${key}">${b.name}</option>`).join('')}</select></label><label id="eventRewardLabel${i}">Reward<select id="eventReward${i}">${Object.entries(REWARDS).map(([key,reward])=>`<option value="${key}">${reward.name}</option>`).join('')}</select></label><label id="eventMessageLabel${i}" style="grid-column:1 / -1">Message text<textarea id="eventMessage${i}" maxlength="500" rows="3" placeholder="Mayor, our population has reached {population}."></textarea></label><label id="eventStatusLabel${i}"><input id="eventStatus${i}" type="checkbox" checked>Include Scenario status button</label><label>Month<input id="eventMonth${i}" type="number" min="1" max="1200" value="${3+i*6}"></label><label>Occurrences<input id="eventCount${i}" type="number" min="1" max="12" value="1"></label><label>Months between occurrences<input id="eventRepeat${i}" type="number" min="1" max="1199" value="6"></label><label>Map X<input id="eventX${i}" type="number" min="1" max="48" value="24"></label><label>Map Y<input id="eventY${i}" type="number" min="1" max="48" value="24"></label>${conditionFields(i,'Condition 1')}<details style="grid-column:1 / -1"><summary>Combine conditions (optional)</summary><label>Trigger when<select id="eventMatch${i}"><option value="all">All selected conditions are true (AND)</option><option value="any">Any selected condition is true (OR)</option></select></label>${[1,2,3].map(j=>`<div class="service-funding">${conditionFields(i+'_'+j,'Condition '+(j+1))}</div>`).join('')}</details></div>`).join('')}</details><p id="customError" role="alert"></p><p>Beginning captures this city as the replayable starting point. Scenario status can restart it or export the playable start for another player. Export current progress separately to keep an attempt.</p><div class="actions"><button id="exportCustomStart">Export starting city</button><button id="startCustom" class="primary">Begin challenge in this city</button><button id="cancelCustom">Back</button></div><p class="fine">This editor supports timed metric goals. The full manual’s scenario scripting language remains unfinished.</p>`);
 $('#insertStoryValue').onclick=()=>{const input=$('#'+$('#storyTarget').value),token='{'+$('#storyValue').value+'}';if(input.value.length-(input.selectionEnd-input.selectionStart)+token.length>1500){$('#storyPreview').textContent='The message would exceed 1,500 characters.';return;}input.setRangeText(token,input.selectionStart,input.selectionEnd,'end');input.focus();};
 $('#previewStory').onclick=()=>{$('#storyPreview').textContent=expandScenarioText($('#'+$('#storyTarget').value).value,c)||'This message is empty.';};
 const targetControl=(id,m)=>{const old=$('#'+id);old.outerHTML=m?.states?`<select id="${id}">${m.states.map((label,value)=>`<option value="${value}" ${value===m.initial?'selected':''}>${label}</option>`).join('')}</select>`:`<input id="${id}" type="number" step="any">`;return $('#'+id);};
 const change=i=>{const m=CUSTOM_METRICS[$('#customMetric'+i).value],input=targetControl('customTarget'+i,m);refreshAreaFields('goal'+i,m);input.disabled=!m;if(m){input.min=m.min||0;input.max=m.max;input.value=m.initial;}};for(let i=0;i<4;i++){change(i);$('#customMetric'+i).onchange=()=>change(i);}
 for(let i=0;i<4;i++){const operation=()=>{const op=$('#eventOperation'+i).value;$('#eventValue'+i).closest('label').hidden=!['set','add'].includes(op);$('#eventCopyMetric'+i).closest('label').hidden=op!=='copy';$('#eventCalculationFields'+i).hidden=op!=='calculate';};$('#eventOperation'+i).onchange=operation;operation();for(const side of ['left','right']){const changeOperand=()=>{const metric=$('#eventOperandKind'+side+i).value==='metric';$('#eventOperandValue'+side+i).closest('label').hidden=metric;$('#eventOperandMetric'+side+i).closest('label').hidden=!metric;};$('#eventOperandKind'+side+i).onchange=changeOperand;changeOperand();}const eventType=()=>{const ending=$('#customEvent'+i).value==='ending';$('#eventOutcomeLabel'+i).hidden=!ending;$('#eventOutcome'+i).disabled=!ending;$('#eventCount'+i).disabled=ending;if(ending)$('#eventCount'+i).value=1;$('#eventRepeat'+i).disabled=ending||Number($('#eventCount'+i).value)<=1;const variable=$('#customEvent'+i).value==='variable';$('#eventVariableFields'+i).hidden=!variable;for(const id of ['eventVariable','eventOperation','eventValue','eventCopyMetric'])$('#'+id+i).disabled=!variable;const copy=$('#eventOperation'+i).value==='copy';$('#eventValue'+i).disabled=!variable||copy;$('#eventCopyMetric'+i).disabled=!variable||!copy;const camera=$('#customEvent'+i).value==='camera',sound=$('#customEvent'+i).value==='sound',popup=$('#customEvent'+i).value==='popup',news=['announcement','popup','ending'].includes($('#customEvent'+i).value),reward=$('#customEvent'+i).value==='reward',business=$('#customEvent'+i).value==='business';$('#eventZoomLabel'+i).hidden=!camera;$('#eventZoom'+i).disabled=!camera;$('#eventSoundLabel'+i).hidden=!sound;$('#eventSound'+i).disabled=!sound;$('#eventStatusLabel'+i).hidden=!popup;$('#eventStatus'+i).disabled=!popup;$('#eventBusinessLabel'+i).hidden=!business;$('#eventBusiness'+i).disabled=!business;$('#eventRewardLabel'+i).hidden=!reward;$('#eventReward'+i).disabled=!reward;$('#eventMessageLabel'+i).hidden=!news;$('#eventMessage'+i).disabled=!news;$('#eventX'+i).disabled=news||reward||business||sound||variable;$('#eventY'+i).disabled=news||reward||business||sound||variable;};$('#customEvent'+i).onchange=eventType;$('#eventOperation'+i).onchange=eventType;eventType();const repeat=()=>{$('#eventRepeat'+i).disabled=Number($('#eventCount'+i).value)<=1;};$('#eventCount'+i).oninput=repeat;repeat();for(const id of [i,i+'_1',i+'_2',i+'_3','rank'+i,'rank'+i+'_1','rank'+i+'_2','rank'+i+'_3']){const refresh=()=>{const m=CUSTOM_METRICS[$('#eventCondition'+id).value],input=targetControl('eventThreshold'+id,m);refreshAreaFields('event'+id,m);input.disabled=!m;const operator=$('#eventOperator'+id);operator.innerHTML=m?.states?'<option value="eq">Is</option>':'<option value="gte">At least</option><option value="lte">At most</option>';operator.disabled=!m;if(m){input.min=m.min||0;input.max=m.max;input.value=m.initial;}};$('#eventCondition'+id).onchange=refresh;refresh();}}
 const readCondition=i=>{const conditions=[i,i+'_1',i+'_2',i+'_3'].filter(id=>$('#eventCondition'+id).value).map(id=>({metric:$('#eventCondition'+id).value,area:readAreaFields('event'+id),operator:$('#eventOperator'+id).value,target:$('#eventThreshold'+id).value.trim()===''?NaN:Number($('#eventThreshold'+id).value)}));return conditions.length?{match:$('#eventMatch'+i).value,conditions}:null;};
 $('#exportCustomStart').onclick=exportCity;$('#cancelCustom').onclick=done;$('#startCustom').onclick=()=>{try{const definition={completionMode:$('#customCompletionMode').value,ranks:[0,1,2,3].filter(i=>$('#rankName'+i).value.trim()).map(i=>({name:$('#rankName'+i).value,outcome:$('#rankOutcome'+i).value,message:$('#rankMessage'+i).value,condition:readCondition('rank'+i)})),variables:[0,1,2,3].map(i=>({name:$('#variableName'+i).value,initial:$('#variableInitial'+i).value.trim()===''?NaN:Number($('#variableInitial'+i).value)})),objectiveMode:$('#customObjectiveMode').value,eventMode:$('#customEventMode').value,speed:{initial:Number($('#customSpeed').value),locked:$('#customSpeedLocked').checked},title:$('#customTitle').value,briefing:$('#customBriefing').value,winMessage:$('#customWinMessage').value,lossMessage:$('#customLossMessage').value,months:Number($('#customMonths').value),holdMonths:Number($('#customHoldMonths').value),events:[0,1,2,3].filter(i=>$('#customEvent'+i).value).map(i=>({type:$('#customEvent'+i).value,outcome:$('#eventOutcome'+i).value,variable:Number($('#eventVariable'+i).value),operation:$('#eventOperation'+i).value,calculation:$('#eventCalculation'+i).value,...Object.fromEntries(['left','right'].map(side=>[side,$('#eventOperandKind'+side+i).value==='metric'?{kind:'metric',metric:$('#eventOperandMetric'+side+i).value}:{kind:'constant',value:$('#eventOperandValue'+side+i).value.trim()===''?NaN:Number($('#eventOperandValue'+side+i).value)}])),value:$('#eventValue'+i).value.trim()===''?NaN:Number($('#eventValue'+i).value),metric:$('#eventCopyMetric'+i).value,zoom:Number($('#eventZoom'+i).value)/100,sound:$('#eventSound'+i).value,business:$('#eventBusiness'+i).value,reward:$('#eventReward'+i).value,message:$('#eventMessage'+i).value,showStatus:$('#eventStatus'+i).checked,month:Number($('#eventMonth'+i).value),repeatCount:Number($('#eventCount'+i).value),repeatEvery:Number($('#eventRepeat'+i).value),x:Number($('#eventX'+i).value)-1,y:Number($('#eventY'+i).value)-1,condition:readCondition(i)})),objectives:[0,1,2,3].filter(i=>$('#customMetric'+i).value).map(i=>({metric:$('#customMetric'+i).value,area:readAreaFields('goal'+i),target:$('#customTarget'+i).value.trim()===''?NaN:Number($('#customTarget'+i).value)}))};attachCustomScenario(c,definition);clearUndo?.();save();update();done();ui.beginCustom?.();}catch(e){$('#customError').textContent=e.message;}};
}
